'use client';

import { useEffect, useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { countOf, nounOf } from '@/registry/ndeko/lib/words';
import { Accordion } from '@/registry/ndeko/ui/accordion';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { AskPerson } from './ask-person';
import { Collapse } from './collapse';
import { PERSON, QUESTIONS, SECTION, TOPICS, type Question } from './data';
import { anchorOf, linkOf, useLinkedQuestion } from './hash';
import { QuestionRow } from './question-row';
import { SearchField } from './search-field';
import { hitsOf, inTopic, topicCountsOf, wordsOf } from './search';
import {
  COPIED_MS,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
} from './session';
import { TopicChips } from './topic-chips';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const QUESTION_WORDS = ['question', 'questions'];

function scrollBehaviorOf(shouldReduceMotion: boolean): ScrollBehavior {
  if (shouldReduceMotion) {
    return 'auto';
  }
  return 'smooth';
}

function spokenLineOf(
  copiedId: string | null,
  shown: number,
  isEmpty: boolean
) {
  if (copiedId !== null) {
    return 'Link copied';
  }
  if (isEmpty) {
    return `No question matches. ${PERSON.firstName} can answer by email.`;
  }
  return `${countOf(shown, 'question')} shown`;
}

function dividerOf(isFirstShown: boolean) {
  if (isFirstShown) {
    return undefined;
  }
  return 'hairline-t border-border';
}

function idsOf(value: unknown[]) {
  return value.filter((item): item is string => typeof item === 'string');
}

export default function Faqs03() {
  const {
    ref,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
    takeOver,
  } = useSession(SESSION);
  const shouldReduceMotion = usePrefersReducedMotion();
  const listId = useId();
  const linkedFromAddress = useLinkedQuestion();
  const words = wordsOf(state.query);
  const hits = hitsOf(state.query);
  const counts = topicCountsOf(hits);
  const visible = inTopic(hits, state.topic);
  const shownIds = visible.map((hit) => hit.question.id);
  const firstShownId = shownIds[0];
  const isEmpty = visible.length === 0;
  const isInOtherTopics = isEmpty && hits.length > 0;
  const topic = TOPICS.find((candidate) => candidate.id === state.topic);
  const topicLabel = topic?.label ?? 'this topic';
  const shownLine = spokenLineOf(state.copiedId, visible.length, isEmpty);
  const message = spokenUnless(isAutoplaying, shownLine);
  const canReplay = isFinished && !isAutoplaying;
  const copiedId = state.copiedId;
  const linkedId = state.linkedId;

  useKeptHeight(ref);

  useEffect(() => {
    if (linkedFromAddress === null) {
      return;
    }
    takeOver();
    act({ type: 'linked', id: linkedFromAddress });
  }, [linkedFromAddress, takeOver, act]);

  useEffect(() => {
    if (linkedId === null) {
      return;
    }
    const frame = requestAnimationFrame(() => {
      const selector = `[id="${anchorOf(linkedId)}"]`;
      const row = ref.current?.querySelector<HTMLElement>(selector);
      const behavior = scrollBehaviorOf(shouldReduceMotion);
      row?.scrollIntoView({ block: 'nearest', behavior });
    });
    return () => cancelAnimationFrame(frame);
  }, [linkedId, shouldReduceMotion, ref]);

  useEffect(() => {
    if (copiedId === null) {
      return;
    }
    const timer = setTimeout(() => act({ type: 'copyCleared' }), COPIED_MS);
    return () => clearTimeout(timer);
  }, [copiedId, act]);

  async function copyLink(questionId: string) {
    try {
      await navigator.clipboard.writeText(linkOf(questionId));
    } catch {
      return;
    }
    act({ type: 'copied', id: questionId });
  }

  function hitOf(question: Question) {
    const found = visible.find((hit) => hit.question.id === question.id);
    return found ?? { question, inQuestion: false, inAnswer: false };
  }

  function changeOpen(value: unknown[]) {
    act({ type: 'opened', ids: idsOf(value) });
  }

  return (
    <div ref={ref} className='@container min-h-[58rem]'>
      <section className='px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <div className='mx-auto flex max-w-3xl flex-col gap-8'>
          <header className='flex flex-col gap-3'>
            <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground max-w-xl text-base text-pretty'>
              {SECTION.description}
            </p>
          </header>
          <div className='flex flex-col gap-3'>
            <SearchField
              query={state.query}
              listId={listId}
              isClearPressed={pressed === 'clear'}
              onType={(value) => act({ type: 'typed', value })}
              onClear={() => act({ type: 'cleared' })}
            />
            <TopicChips
              topic={state.topic}
              counts={counts}
              pressed={pressed}
              onPick={(next) => act({ type: 'topicPicked', topic: next })}
            />
          </div>
          <div id={listId} className='flex flex-col gap-4'>
            <Accordion value={state.openIds} onValueChange={changeOpen}>
              {QUESTIONS.map((question) => (
                <Collapse
                  key={question.id}
                  isShown={shownIds.includes(question.id)}
                >
                  <div
                    className={cn(
                      'px-[3px] py-[3px]',
                      dividerOf(firstShownId === question.id)
                    )}
                  >
                    <QuestionRow
                      hit={hitOf(question)}
                      words={words}
                      isTriggerPressed={pressed === `trigger-${question.id}`}
                      isCopyPressed={pressed === `copy-${question.id}`}
                      isCopied={copiedId === question.id}
                      onCopy={copyLink}
                    />
                  </div>
                </Collapse>
              ))}
            </Accordion>
            <Collapse isShown={isEmpty}>
              <div className='p-[3px]'>
                <AskPerson
                  query={state.query}
                  topicLabel={topicLabel}
                  isInOtherTopics={isInOtherTopics}
                  isClearPressed={pressed === 'clear-search'}
                  onClear={() => act({ type: 'cleared' })}
                  onAllTopics={() => act({ type: 'topicPicked', topic: 'all' })}
                />
              </div>
            </Collapse>
            <div className='flex min-h-8 items-center justify-between gap-3'>
              <p className='text-muted-foreground flex items-baseline gap-1 text-xs tabular-nums'>
                <MotionNumber value={visible.length} />
                <WordRoll
                  text={nounOf(visible.length, 'question')}
                  labels={QUESTION_WORDS}
                />
              </p>
              <ReplayButton
                isShown={canReplay}
                onReplay={restart}
                label='Replay'
              />
            </div>
          </div>
        </div>
      </section>
      <LiveRegion message={message} />
    </div>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Button } from '@/registry/ndeko/ui/button';

import { PERSON } from './data';

type AskPersonProps = {
  query: string;
  topicLabel: string;
  isInOtherTopics: boolean;
  isClearPressed: boolean;
  onClear: () => void;
  onAllTopics: () => void;
};

export function AskPerson({
  query,
  topicLabel,
  isInOtherTopics,
  isClearPressed,
  onClear,
  onAllTopics,
}: AskPersonProps) {
  const title = `Nothing matches “${query}”`;
  const titleInTopic = `Nothing in ${topicLabel} matches “${query}”`;
  let heading = title;
  if (isInOtherTopics) {
    heading = titleInTopic;
  }

  return (
    <div className='bg-foreground/[0.04] flex flex-col gap-4 rounded-xl p-4 @md:flex-row @md:items-center @md:p-5'>
      <Avatar seed={PERSON.name} className='size-10' />
      <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
        <p className='text-sm font-medium break-words'>{heading}</p>
        <p className='text-muted-foreground text-[13px] text-pretty'>
          {PERSON.name}, {PERSON.role}, answers by email within a day.
        </p>
      </div>
      <div className='flex flex-wrap gap-2'>
        <Button nativeButton={false} render={<a href={PERSON.href} />}>
          Ask {PERSON.firstName}
        </Button>
        {isInOtherTopics && (
          <Button variant='outline' onClick={onAllTopics}>
            Search all topics
          </Button>
        )}
        <Button
          variant='ghost'
          onClick={onClear}
          className={cn(pressedQuietOf(isClearPressed))}
        >
          Clear search
        </Button>
      </div>
    </div>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

type CollapseProps = {
  isShown: boolean;
  className?: string;
  children: React.ReactNode;
};

/**
 * Rows that come and go while a list is filtered stay in the page: a closed row has no height,
 * no opacity and takes no focus, so the others close ranks and nothing is mounted again.
 */
export function Collapse({ isShown, className, children }: CollapseProps) {
  return (
    <div
      data-shown={isShown}
      inert={!isShown}
      className={cn(
        'grid grid-rows-[1fr] opacity-100 transition-[grid-template-rows,opacity] duration-200 ease-(--ease-out-strong) data-[shown=false]:grid-rows-[0fr] data-[shown=false]:opacity-0 motion-reduce:transition-none',
        className
      )}
    >
      <div className='min-h-0 overflow-hidden'>{children}</div>
    </div>
  );
}

import { useSyncExternalStore } from 'react';

import { QUESTIONS } from './data';

const ANCHOR_PREFIX = 'faq-';

export function anchorOf(questionId: string) {
  return `${ANCHOR_PREFIX}${questionId}`;
}

export function questionIdOfHash(hash: string) {
  const anchor = hash.replace('#', '');
  const found = QUESTIONS.find((question) => anchorOf(question.id) === anchor);
  return found?.id ?? null;
}

export function linkOf(questionId: string) {
  const { origin, pathname } = window.location;
  return `${origin}${pathname}#${anchorOf(questionId)}`;
}

function subscribe(onChange: () => void) {
  window.addEventListener('hashchange', onChange);
  return () => window.removeEventListener('hashchange', onChange);
}

function currentHash() {
  return window.location.hash;
}

function serverHash() {
  return '';
}

export function useLinkedQuestion() {
  const hash = useSyncExternalStore(subscribe, currentHash, serverHash);
  return questionIdOfHash(hash);
}

import { markedPartsOf, type MarkedPart } from './search';

/** A mark keeps the browser's yellow unless its background is set. */
const MARK = 'rounded-[3px] bg-primary/15 text-inherit';

function Part({ part }: { part: MarkedPart }) {
  if (part.isMatch) {
    return <mark className={MARK}>{part.text}</mark>;
  }
  return <span>{part.text}</span>;
}

type MarkedTextProps = {
  text: string;
  words: string[];
};

export function MarkedText({ text, words }: MarkedTextProps) {
  const parts = markedPartsOf(text, words);

  return (
    <>
      {parts.map((part) => (
        <Part key={part.key} part={part} />
      ))}
    </>
  );
}

'use client';

import { WordRoll } from '@/components/core/word-roll';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { CheckIcon, LinkIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/registry/ndeko/ui/accordion';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import { anchorOf } from './hash';
import { MarkedText } from './marked-text';
import type { Hit } from './search';

const COPY_LABELS = ['Copy link', 'Link copied'];

function copyLabelOf(isCopied: boolean) {
  if (isCopied) {
    return 'Link copied';
  }
  return 'Copy link';
}

type QuestionRowProps = {
  hit: Hit;
  words: string[];
  isTriggerPressed: boolean;
  isCopyPressed: boolean;
  isCopied: boolean;
  onCopy: (questionId: string) => void;
};

export function QuestionRow({
  hit,
  words,
  isTriggerPressed,
  isCopyPressed,
  isCopied,
  onCopy,
}: QuestionRowProps) {
  const { question } = hit;
  const isSearching = words.length > 0;
  const missesQuestion = !hit.inQuestion;
  const matchesAnswer = hit.inAnswer;
  const isAnswerOnly = isSearching && missesQuestion && matchesAnswer;
  const copyLabel = copyLabelOf(isCopied);

  return (
    <AccordionItem
      value={question.id}
      id={anchorOf(question.id)}
      className='scroll-mt-4'
    >
      <AccordionTrigger
        className={cn('text-sm', pressedQuietOf(isTriggerPressed))}
      >
        <span className='flex min-w-0 flex-col gap-0.5'>
          <span className='text-balance'>
            <MarkedText text={question.question} words={words} />
          </span>
          {isAnswerOnly && (
            <span className='text-muted-foreground text-xs font-normal'>
              Matches in the answer
            </span>
          )}
        </span>
      </AccordionTrigger>
      <AccordionContent className='px-1 text-sm leading-relaxed text-pretty'>
        <p>
          <MarkedText text={question.answer} words={words} />
        </p>
        <Button
          type='button'
          variant='ghost'
          size='sm'
          onClick={() => onCopy(question.id)}
          className={cn(
            'text-muted-foreground mt-3',
            pressedQuietOf(isCopyPressed)
          )}
        >
          <Swap swapKey={String(isCopied)}>
            {isCopied && <CheckIcon />}
            {!isCopied && <LinkIcon />}
          </Swap>
          <WordRoll text={copyLabel} labels={COPY_LABELS} />
        </Button>
      </AccordionContent>
    </AccordionItem>
  );
}

'use client';

import { useId } from 'react';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { SearchIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';

import { SECTION } from './data';

type SearchFieldProps = {
  query: string;
  listId: string;
  isClearPressed: boolean;
  onType: (value: string) => void;
  onClear: () => void;
};

export function SearchField({
  query,
  listId,
  isClearPressed,
  onType,
  onClear,
}: SearchFieldProps) {
  const inputId = useId();
  const hasQuery = query !== '';

  function clearOnEscape(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape' && hasQuery) {
      event.preventDefault();
      onClear();
    }
  }

  return (
    <div className='relative'>
      <label htmlFor={inputId} className='sr-only'>
        {SECTION.searchLabel}
      </label>
      <SearchIcon className='text-muted-foreground pointer-events-none absolute start-3 top-1/2 size-4 -translate-y-1/2' />
      <Input
        id={inputId}
        type='search'
        size='lg'
        autoComplete='off'
        spellCheck={false}
        placeholder={SECTION.searchPlaceholder}
        aria-controls={listId}
        value={query}
        onChange={(event) => onType(event.target.value)}
        onKeyDown={clearOnEscape}
        className='ps-9 pe-10'
      />
      {hasQuery && (
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label='Clear the search'
          onClick={onClear}
          className={cn(
            'text-muted-foreground absolute end-1 top-1/2 -translate-y-1/2',
            pressedQuietOf(isClearPressed)
          )}
        >
          <XIcon />
        </Button>
      )}
    </div>
  );
}

import { QUESTIONS, TOPICS, type Question, type TopicFilter } from './data';

export type MarkedPart = {
  key: string;
  text: string;
  isMatch: boolean;
};

export type Hit = {
  question: Question;
  inQuestion: boolean;
  inAnswer: boolean;
};

type Folded = {
  text: string;
  /** For each folded character, where its source character starts and ends in the original text. */
  starts: number[];
  ends: number[];
};

type Range = {
  start: number;
  end: number;
};

type Indexed = {
  question: Question;
  questionText: string;
  answerText: string;
};

const ACCENTS = /\p{M}/gu;

/** One letter matches half the list, so a word counts from two letters. */
const MIN_WORD_LENGTH = 2;

function foldedCharOf(char: string) {
  const decomposed = char.normalize('NFD');
  const bare = decomposed.replace(ACCENTS, '');
  return bare.toLowerCase();
}

export function foldedOf(text: string): Folded {
  const starts: number[] = [];
  const ends: number[] = [];
  let folded = '';
  let position = 0;
  for (const char of text) {
    const part = foldedCharOf(char);
    const end = position + char.length;
    for (let index = 0; index < part.length; index += 1) {
      starts.push(position);
      ends.push(end);
    }
    folded += part;
    position = end;
  }
  return { text: folded, starts, ends };
}

export function wordsOf(query: string) {
  const folded = foldedOf(query).text;
  const pieces = folded.split(/\s+/);
  return pieces.filter((piece) => piece.length >= MIN_WORD_LENGTH);
}

const INDEX: Indexed[] = QUESTIONS.map((question) => ({
  question,
  questionText: foldedOf(question.question).text,
  answerText: foldedOf(question.answer).text,
}));

function holdsWord(entry: Indexed, word: string) {
  const inQuestion = entry.questionText.includes(word);
  const inAnswer = entry.answerText.includes(word);
  return inQuestion || inAnswer;
}

function hitOf(entry: Indexed, words: string[]): Hit | null {
  const holdsEveryWord = words.every((word) => holdsWord(entry, word));
  if (!holdsEveryWord) {
    return null;
  }
  const inQuestion = words.some((word) => entry.questionText.includes(word));
  const inAnswer = words.some((word) => entry.answerText.includes(word));
  return { question: entry.question, inQuestion, inAnswer };
}

export function hitsOf(query: string): Hit[] {
  const words = wordsOf(query);
  const hits: Hit[] = [];
  for (const entry of INDEX) {
    const hit = hitOf(entry, words);
    if (hit) {
      hits.push(hit);
    }
  }
  return hits;
}

export function inTopic(hits: Hit[], topic: TopicFilter) {
  if (topic === 'all') {
    return hits;
  }
  return hits.filter((hit) => hit.question.topic === topic);
}

export function topicCountsOf(hits: Hit[]) {
  const counts: Record<string, number> = {};
  for (const topic of TOPICS) {
    counts[topic.id] = inTopic(hits, topic.id).length;
  }
  return counts;
}

function rangesOfWord(folded: Folded, word: string) {
  const ranges: Range[] = [];
  let from = folded.text.indexOf(word);
  while (from !== -1) {
    const last = from + word.length - 1;
    ranges.push({ start: folded.starts[from], end: folded.ends[last] });
    from = folded.text.indexOf(word, from + word.length);
  }
  return ranges;
}

function byStart(first: Range, second: Range) {
  return first.start - second.start;
}

function mergedRanges(ranges: Range[]) {
  const sorted = [...ranges].sort(byStart);
  const merged: Range[] = [];
  for (const range of sorted) {
    const previous = merged.at(-1);
    const overlaps = previous !== undefined && range.start <= previous.end;
    if (overlaps) {
      previous.end = Math.max(previous.end, range.end);
      continue;
    }
    merged.push({ ...range });
  }
  return merged;
}

export function markedPartsOf(text: string, words: string[]) {
  const folded = foldedOf(text);
  const ranges = words.flatMap((word) => rangesOfWord(folded, word));
  const parts: MarkedPart[] = [];
  let cursor = 0;
  for (const range of mergedRanges(ranges)) {
    if (range.start > cursor) {
      const plain = text.slice(cursor, range.start);
      parts.push({ key: String(cursor), text: plain, isMatch: false });
    }
    const match = text.slice(range.start, range.end);
    parts.push({ key: String(range.start), text: match, isMatch: true });
    cursor = range.end;
  }
  if (cursor < text.length) {
    const rest = text.slice(cursor);
    parts.push({ key: String(cursor), text: rest, isMatch: false });
  }
  return parts;
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import type { TopicFilter } from './data';

export type FaqState = {
  query: string;
  topic: TopicFilter;
  openIds: string[];
  copiedId: string | null;
  linkedId: string | null;
};

export type FaqAction =
  | { type: 'typed'; value: string }
  | { type: 'topicPicked'; topic: TopicFilter }
  | { type: 'opened'; ids: string[] }
  | { type: 'cleared' }
  | { type: 'copied'; id: string }
  | { type: 'copyCleared' }
  | { type: 'linked'; id: string };

type Step = SessionStep<FaqState, FaqAction>;

export const INITIAL: FaqState = {
  query: '',
  topic: 'all',
  openIds: [],
  copiedId: null,
  linkedId: null,
};

export function reducer(state: FaqState, action: FaqAction): FaqState {
  switch (action.type) {
    case 'typed':
      return { ...state, query: action.value };
    case 'topicPicked':
      return { ...state, topic: action.topic };
    case 'opened':
      return { ...state, openIds: action.ids };
    case 'cleared':
      return { ...state, query: '' };
    case 'copied':
      return { ...state, copiedId: action.id };
    case 'copyCleared':
      return { ...state, copiedId: null };
    case 'linked':
      return {
        ...state,
        query: '',
        topic: 'all',
        openIds: [action.id],
        linkedId: action.id,
      };
  }
}

export const COPIED_MS = 1600;

const KEY_MS = 260;

function typing(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((value, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'typed', value },
  }));
}

/**
 * Someone types "cafe" and finds the question with its accent, opens it and copies its link,
 * clears the search and filters by topic, then types a word nothing matches and meets the person
 * to ask.
 */
export const SCRIPT: Step[] = [
  ...typing('cafe', 1000),
  {
    after: 1500,
    by: 'demo',
    press: 'trigger-split',
    action: { type: 'opened', ids: ['split'] },
  },
  {
    after: 1700,
    by: 'demo',
    press: 'copy-split',
    action: { type: 'copied', id: 'split' },
  },
  {
    after: 2400,
    by: 'demo',
    press: 'clear',
    action: { type: 'cleared' },
  },
  {
    after: 1500,
    by: 'demo',
    press: 'topic-payments',
    action: { type: 'topicPicked', topic: 'payments' },
  },
  {
    after: 1800,
    by: 'demo',
    press: 'topic-all',
    action: { type: 'topicPicked', topic: 'all' },
  },
  ...typing('zzq', 1400),
